  // driver-fleet
  'help.driver-fleet.title': 'Join or leave a fleet',
  'help.driver-fleet.summary': 'A fleet takes you on by offering you a place. You say yes or no in the app. No code is typed anywhere.',
  'help.driver-fleet.step1': 'Give the fleet office the phone number you sign in with.',
  'help.driver-fleet.step2': 'When they offer you a place, it shows on your home screen, and under your picture, then Your fleet.',
