  // business-people
  'help.business-people.title': 'Add and remove people in your business',
  'help.business-people.summary': 'An owner adds people by the phone number they sign in with. Nothing opens for them until they sign in themselves and say yes.',
  'help.business-people.step1': '“People › Add someone”: their phone number, their name, and what they may do.',
